import java.util.*;

class Solution {
    public int maxProduct(TreeNode root) {

        final long MOD=1000000007L;
        ArrayList<TreeNode>order=new ArrayList<>(); ArrayDeque<TreeNode>st=new ArrayDeque<>(); st.push(root);
        long total=0;
        while(!st.isEmpty()){TreeNode n=st.pop();order.add(n);total+=n.val;if(n.left!=null)st.push(n.left);if(n.right!=null)st.push(n.right);}
        IdentityHashMap<TreeNode,Long>sum=new IdentityHashMap<>(); long best=0;
        for(int i=order.size()-1;i>=0;i--){TreeNode n=order.get(i);long s=n.val+sum.getOrDefault(n.left,0L)+sum.getOrDefault(n.right,0L);sum.put(n,s);if(n!=root)best=Math.max(best,s*(total-s));}
        return best%MOD;

    }
}

